// Simple endless runner for canvas with id="game"
// Player jumps on click/tap, avoids incoming obstacles.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 400;

  // Player
  const player = {
    x: 50,
    y: height - 50,
    width: 30,
    height: 30,
    vy: 0,
    jumpStrength: -12,
    gravity: 0.5,
    onGround: true,
    draw() {
      ctx.fillStyle = '#ff8800';
      ctx.fillRect(this.x, this.y, this.width, this.height);
    },
    update() {
      this.vy += this.gravity;
      this.y += this.vy;
      if (this.y + this.height >= height) {
        this.y = height - this.height;
        this.vy = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
    },
    jump() {
      if (this.onGround) {
        this.vy = this.jumpStrength;
        this.onGround = false;
      }
    },
  };

  // Obstacles
  const obstacles = [];
  let obstacleTimer = 0;
  const obstacleInterval = 90; // frames

  function spawnObstacle() {
    const size = 20 + Math.random() * 30;
    obstacles.push({
      x: width,
      y: height - size,
      width: size,
      height: size,
      speed: 4 + Math.random() * 2,
    });
  }

  function updateObstacles() {
    obstacleTimer++;
    if (obstacleTimer > obstacleInterval) {
      spawnObstacle();
      obstacleTimer = 0;
    }
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= o.speed;
      if (o.x + o.width < 0) obstacles.splice(i, 1);
    }
  }

  function drawObstacles() {
    ctx.fillStyle = '#333';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.width, o.height);
    }
  }

  function checkCollision() {
    for (const o of obstacles) {
      if (
        player.x < o.x + o.width &&
        player.x + player.width > o.x &&
        player.y < o.y + o.height &&
        player.y + player.height > o.y
      ) {
        // simple game over: stop animation
        cancelAnimationFrame(frameId);
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = '#fff';
        ctx.font = '30px sans-serif';
        ctx.fillText('Game Over', width / 2 - 80, height / 2);
        return true;
      }
    }
    return false;
  }

  // Input
  canvas.addEventListener('mousedown', () => player.jump());
  canvas.addEventListener('touchstart', (e) => { e.preventDefault(); player.jump(); }, { passive: false });

  // Score
  let score = 0;
  function drawScore() {
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  }

  // Main loop
  let frameId;
  function loop() {
    ctx.clearRect(0, 0, width, height);
    player.update();
    updateObstacles();
    player.draw();
    drawObstacles();
    drawScore();
    if (!checkCollision()) {
      score += 0.1;
      frameId = requestAnimationFrame(loop);
    }
  }

  loop();
})();
